-- Questie-X-WHE: teaches Questie-X the world maps this server's DBCs add or move (Open Azeroth's zones, Pandaria),
-- so the arrow, coordinates and zone names work there. Data.lua is generated by tools/questie/questie_whe.py from the
-- realm's WorldMapArea, Map and AreaTable DBCs; this file is copied unchanged.
--
-- Questie-X finds the player's map with GetCurrentMapAreaID() -> UiMapData (bounds per map). A map it doesn't know
-- falls back to the empty "Cosmic" map, so the player has no world position and the arrow hides.
--   moved: stock maps the server moved (Azuremyst, Eversong, ...): their UiMapData entry gets the new bounds
--   zones: maps stock lacks: added under 100000 + their GetCurrentMapAreaID() value (WorldMapArea id + 1), which
--          GetCurrentUiMapID returns for them (keys below 100000 are retail uiMapIds Questie already uses)
--          Stock maps that kept their continent but changed bounds come here too (flag z[9]), for the player's
--          position only: Questie's spawn coordinates stay relative to the stock entry
--   areas: area names Questie lacks (otherwise "Unknown Zone")

local realm = GetRealmName and GetRealmName()
local data = QuestieWHE_Data[realm]
if not data then
    local _, first = next(QuestieWHE_Data)
    data = first
end
if not data or not QuestieCompat or not QuestieCompat.UiMapData then
    return
end

local KEY_BASE = 100000
local keyByMapAreaId = {}

local function apply()
    local UiMapData = QuestieCompat.UiMapData

    for _, entry in pairs(UiMapData) do
        local m = entry.mapID and data.moved[entry.mapID]
        if m then
            entry[1], entry[2], entry[3], entry[4], entry.instance = m[1], m[2], m[3], m[4], m[5]
        end
    end

    -- continents first, so zones can name their parent
    local continentByInstance = {}
    for id, entry in pairs(UiMapData) do
        if entry.mapType == 2 and entry.instance and not continentByInstance[entry.instance] then
            continentByInstance[entry.instance] = id
        end
    end
    for pass = 2, 3 do
        for mapAreaId, z in pairs(data.zones) do
            if z[8] == pass then
                local key = KEY_BASE + mapAreaId
                UiMapData[key] = {
                    z[1], z[2], z[3], z[4],
                    mapType = pass,
                    parentMapID = pass == 3 and continentByInstance[z[5]] or 946,
                    mapID = mapAreaId,
                    instance = z[5],
                    name = z[7],
                }
                keyByMapAreaId[mapAreaId] = key
                if pass == 2 then
                    continentByInstance[z[5]] = continentByInstance[z[5]] or key
                end
            end
        end
    end

    local ZoneDB = QuestieLoader and QuestieLoader:ImportModule("ZoneDB")
    local private = ZoneDB and ZoneDB.private
    if private then
        private.areaIdToUiMapId = private.areaIdToUiMapId or {}
        private.uiMapIdToAreaId = private.uiMapIdToAreaId or {}
        for mapAreaId, z in pairs(data.zones) do
            if z[6] > 0 and not z[9] then -- z[9]: player position only; spawns keep the stock map
                local key = KEY_BASE + mapAreaId
                if private.areaIdToUiMapId[z[6]] == nil then
                    private.areaIdToUiMapId[z[6]] = key
                end
                private.uiMapIdToAreaId[key] = z[6]
            end
        end
    end

    local l10n = QuestieLoader and QuestieLoader:ImportModule("l10n")
    if l10n and l10n.zoneLookup then
        local known = {}
        for _, zoneTable in pairs(l10n.zoneLookup) do
            for areaId in pairs(zoneTable) do
                known[areaId] = true
            end
        end
        for areaId, a in pairs(data.areas) do
            if not known[areaId] then
                l10n.zoneLookup[a[1]] = l10n.zoneLookup[a[1]] or {}
                l10n.zoneLookup[a[1]][areaId] = a[2]
            end
        end
    end
end

apply()

-- GetCurrentPlayerPosition looks this up on QuestieCompat at every call, so wrapping it is enough
local original = QuestieCompat.GetCurrentUiMapID
QuestieCompat.GetCurrentUiMapID = function(...)
    local level = GetCurrentMapDungeonLevel and GetCurrentMapDungeonLevel() or 0
    if level == 0 then
        local key = keyByMapAreaId[GetCurrentMapAreaID()]
        if key then
            return key
        end
    end
    return original(...)
end

local frame = CreateFrame("Frame")
frame:RegisterEvent("PLAYER_LOGIN")
frame:SetScript("OnEvent", function(self)
    self:UnregisterEvent("PLAYER_LOGIN")
    apply()
end)
